<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Sorting Visualizer</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #111827;
      --panel: #1f2937;
      --panel-light: #263449;
      --text: #e5e7eb;
      --muted: #9ca3af;
      --accent: #38bdf8;
      --accent-2: #818cf8;
      --danger: #f87171;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      background: var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      display: flex;
      justify-content: center;
      align-items: center;
      padding: 24px;
    }

    .app {
      width: min(1100px, 100%);
      background: var(--panel);
      border: 1px solid #374151;
      border-radius: 16px;
      padding: 24px;
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
    }

    header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 16px;
      margin-bottom: 20px;
      flex-wrap: wrap;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.4rem, 3vw, 2rem);
      letter-spacing: 0.02em;
    }

    .controls {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
    }

    button {
      border: 0;
      border-radius: 8px;
      padding: 10px 17px;
      color: white;
      background: var(--panel-light);
      font: inherit;
      font-weight: 600;
      cursor: pointer;
      transition: transform 0.15s ease, background 0.15s ease, opacity 0.15s ease;
    }

    button:hover:not(:disabled) {
      transform: translateY(-1px);
      background: #374b67;
    }

    button:active:not(:disabled) {
      transform: translateY(0);
    }

    button:disabled {
      cursor: not-allowed;
      opacity: 0.55;
    }

    #sort {
      background: var(--accent-2);
    }

    #sort:hover:not(:disabled) {
      background: #6d75dc;
    }

    #shuffle {
      background: #0e7490;
    }

    #reset {
      background: #374151;
    }

    #bars {
      height: 390px;
      width: 100%;
      padding: 18px 14px 0;
      display: flex;
      align-items: flex-end;
      gap: 4px;
      overflow: hidden;
      border-radius: 12px;
      background:
        linear-gradient(to top, rgba(255,255,255,0.05) 1px, transparent 1px);
      background-size: 100% 20%;
      border: 1px solid #374151;
    }

    .bar {
      flex: 1 1 0;
      min-width: 2px;
      min-height: 3px;
      border-radius: 5px 5px 0 0;
      background: linear-gradient(to top, var(--accent), var(--accent-2));
      transition: height 0.08s ease, background 0.08s ease;
    }

    .status {
      min-height: 1.4em;
      margin: 14px 2px 0;
      color: var(--muted);
      font-size: 0.9rem;
    }
  </style>
</head>
<body>
  <main class="app">
    <header>
      <h1>Sorting Algorithm Visualizer</h1>
      <div class="controls">
        <button id="sort" type="button">Sort</button>
        <button id="shuffle" type="button">Shuffle</button>
        <button id="reset" type="button">Reset</button>
      </div>
    </header>

    <div id="bars" aria-label="Array visualization"></div>
    <div class="status" id="status" aria-live="polite"></div>
  </main>

  <script>
    (() => {
      const bars = document.getElementById("bars");
      const sortButton = document.getElementById("sort");
      const shuffleButton = document.getElementById("shuffle");
      const resetButton = document.getElementById("reset");
      const status = document.getElementById("status");

      const initialArray = [];
      for (let i = 0; i <  forty(); i++) {
        initialArray.push(10 + Math.floor(Math.random() * 91));
      }

      function forty() {
        return 40;
      }

      let data = initialArray.slice();
      let comparisonIndex = 0;
      let passIndex = 0;
      let sortingDone = false;
      let timer = null;

      function isAscending() {
        for (let i = 1; i < data.length; i++) {
          if (data[i - 1] > data[i]) return false;
        }
        return true;
      }

      function draw() {
        bars.replaceChildren();

        if (data.length === 0) {
          status.textContent = "Empty array";
          return;
        }

        let max = data[0];
        for (const value of data) {
          if (value > max) max = value;
        }
        if (max <= 0) max = 1;

        for (const value of data) {
          const bar = document.createElement("div");
          bar.className = "bar";
          const height = Math.max(3, (Number(value) / max) * 100);
          bar.style.height = `${height}%`;
          bar.title = String(value);
          bars.appendChild(bar);
        }

        status.textContent = sortingDone ? "Sorted ascending" : `${data.length} values`;
      }

      function stopAnimation() {
        if (timer !== null) {
          clearTimeout(timer);
          timer = null;
        }
        sortButton.disabled = false;
        shuffleButton.disabled = false;
        resetButton.disabled = false;
      }

      function setArray(values) {
        stopAnimation();
        data = Array.from(values, Number);
        comparisonIndex = 0;
        passIndex = 0;
        sortingDone = data.length < 2 || isAscending();
        draw();
      }

      function sortStep() {
        if (sortingDone) return true;

        if (data.length < 2) {
          sortingDone = true;
          draw();
          return true;
        }

        // One bubble-sort comparison per call.
        if (data[comparisonIndex] > data[comparisonIndex + 1]) {
          const temporary = data[comparisonIndex];
          data[comparisonIndex] = data[comparisonIndex + 1];
          data[comparisonIndex + 1] = temporary;
        }

        comparisonIndex++;

        if (comparisonIndex >= data.length - 1 - passIndex) {
          comparisonIndex = 0;
          passIndex++;

          if (passIndex >= data.length - 1) {
            sortingDone = true;
          }
        }

        draw();
        return sortingDone;
      }

      function animateSort() {
        if (timer !== null) return;

        sortButton.disabled = true;
        shuffleButton.disabled = true;
        resetButton.disabled = true;

        function tick() {
          const complete = sortStep();
          if (complete) {
            stopAnimation();
          } else {
            timer = setTimeout(() => {
              timer = null;
              tick();
            }, 35);
          }
        }

        tick();
      }

      function shuffle() {
        stopAnimation();
        for (let i = data.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          const temporary = data[i];
          data[i] = data[j];
          data[j] = temporary;
        }
        comparisonIndex = 0;
        passIndex = 0;
        sortingDone = data.length < 2 || isAscending();
        draw();
      }

      function reset() {
        setArray(initialArray);
      }

      sortButton.addEventListener("click", animateSort);
      shuffleButton.addEventListener("click", shuffle);
      resetButton.addEventListener("click", reset);

      window.viz = {
        array: () => data.slice(),
        setArray,
        sortStep,
        sorted: isAscending
      };

      draw();
    })();
  </script>
</body>
</html>
